package auth

import (
	"context"
	"log"
	"strings"

	"charm.land/bubbles/v2/spinner"
	tea "charm.land/bubbletea/v2"
	"github.com/anthnel/devdesk/internal/forge"
	"github.com/anthnel/devdesk/internal/forge/session"
	"github.com/anthnel/devdesk/internal/ui/components"
)

// ForgeAuthSuccessMsg is the successful authentication message (coming from app.go)
type ForgeAuthSuccessMsg struct {
	Forge forge.Forge
	User  forge.User
}

// Update handles updates
func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height

	case tea.KeyPressMsg:
		return m.handleKeyMsg(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)

	case AuthStartMsg:
		m.authenticating = true
		return m, m.spinner.Tick

	case AuthResultMsg:
		return m.handleAuthResult(msg)

	case spinner.TickMsg:
		if m.authenticating {
			m.spinner, cmd = m.spinner.Update(msg)
			return m, cmd
		}

	case CredentialsLoadedMsg:
		return m.handleCredentialsLoaded(msg)

	case ForgeAuthSuccessMsg:
		return m.handleGitLabAuthSuccess(msg)

	case LogoutCompleteMsg:
		return m.handleLogoutComplete()
	}

	m.footer.Handle(msg)
	return m, nil
}

// handleKeyMsg handles keyboard input
func (m *Model) handleKeyMsg(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	if m.authenticating {
		return m, nil
	}

	switch msg.String() {
	case "down":
		m.nextField()
		return m, nil

	case "up":
		m.prevField()
		return m, nil

	case "enter":
		return m.handleEnterKey()

	default:
		return m.handleInputUpdate(msg)
	}
}

// handlePaste gives pasted text to the token field while it has the keyboard.
// It is dropped during a login, and never read as keys (Rule 111).
func (m *Model) handlePaste(msg tea.PasteMsg) (tea.Model, tea.Cmd) {
	if m.authenticating {
		return m, nil
	}
	return m.handleInputUpdate(msg)
}

// handleEnterKey handles the Enter key based on the active field
func (m *Model) handleEnterKey() (tea.Model, tea.Cmd) {
	if m.authenticated {
		return m, m.logout()
	}
	if m.currentField < fieldSubmit {
		m.nextField()
		return m, nil
	}
	// Validate before the spinner: a refused submit starts nothing.
	if !m.validation.Submit(m.tokenErrors()) {
		m.restyleToken()
		return m, nil
	}
	m.restyleToken()
	if m.config.Forge.URL == "" {
		m.error = m.missingURLMessage()
		return m, nil
	}
	m.authenticating = true
	return m, tea.Batch(m.spinner.Tick, m.authenticate())
}

// tokenErrors lists the field errors of the form: the token is required once
// trimmed. The URL is configuration, not a field of this form.
func (m *Model) tokenErrors() []components.FieldError {
	if strings.TrimSpace(m.tokenInput.Value()) == "" {
		return []components.FieldError{{Key: keyToken, Text: "Token is required"}}
	}
	return nil
}

// restyleToken applies the invalid mark to the token field. It runs from
// Update() only, never from a Cmd or View() (Rule 110).
func (m *Model) restyleToken() {
	m.marks.Sync(keyToken, &m.tokenInput, m.validation.Invalid(keyToken))
}

// missingURLMessage is the body error for an unconfigured forge URL.
func (m *Model) missingURLMessage() string {
	return "No " + m.vocab().Name + " URL configured — set it in :config, " + m.forgeTab() + " tab"
}

// handleInputUpdate forwards messages to the active inputs
func (m *Model) handleInputUpdate(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	if m.currentField == fieldToken {
		m.tokenInput, cmd = m.tokenInput.Update(msg)
		m.validation.Revalidate(m.tokenErrors())
		m.restyleToken()
	}
	return m, cmd
}

// handleAuthResult handles the authentication result
func (m *Model) handleAuthResult(msg AuthResultMsg) (tea.Model, tea.Cmd) {
	log.Printf("AUTH: AuthResultMsg received (Error: %v, User: %q)", msg.Error, msg.User.Username)
	m.authenticating = false
	if msg.Error != nil {
		log.Printf("AUTH: Authentication failed: %v", msg.Error)
		m.error = msg.Error.Error()
		m.success = ""
		m.warning = ""
		return m, nil
	}

	log.Printf("AUTH: Authentication successful for user: %s", msg.User.Username)
	m.error = ""
	m.authenticated = true
	m.user = msg.User
	m.success = "✓ Authenticated as " + msg.User.Username
	m.warning = msg.SaveWarning
	m.currentField = fieldToken
	return m, nil
}

// handleCredentialsLoaded handles the credentials loaded from storage
func (m *Model) handleCredentialsLoaded(msg CredentialsLoadedMsg) (tea.Model, tea.Cmd) {
	log.Printf("AUTH: CredentialsLoadedMsg received (URL: %s, Token: %v)", msg.URL, msg.Token != "")
	if msg.URL != "" && strings.TrimSpace(msg.Token) != "" {
		m.tokenInput.SetValue(msg.Token)
		log.Printf("AUTH: Starting auto-login")
		m.authenticating = true
		return m, tea.Batch(m.spinner.Tick, m.authenticate())
	}
	log.Printf("AUTH: No credentials to auto-login")
	return m, nil
}

// handleGitLabAuthSuccess handles the successful authentication coming from app.go
func (m *Model) handleGitLabAuthSuccess(msg ForgeAuthSuccessMsg) (tea.Model, tea.Cmd) {
	m.authenticating = false
	m.authenticated = true
	m.user = msg.User
	m.error = ""
	m.success = "✓ Already authenticated as " + msg.User.Username
	m.currentField = fieldToken
	return m, nil
}

// handleLogoutComplete resets the state after logout
func (m *Model) handleLogoutComplete() (tea.Model, tea.Cmd) {
	m.authenticated = false
	m.user = forge.User{}
	m.currentField = fieldToken
	m.tokenInput.SetValue("")
	m.error = ""
	m.warning = ""
	m.success = "✓ Logged out successfully"
	m.tokenInput.Focus()
	return m, nil
}

// nextField moves to the next field
func (m *Model) nextField() {
	m.currentField++
	if m.currentField > lastField {
		m.currentField = lastField
	}

	m.updateFocus()
}

// prevField moves to the previous field
func (m *Model) prevField() {
	m.currentField--
	if m.currentField < fieldToken {
		m.currentField = fieldToken
	}

	m.updateFocus()
}

// updateFocus updates the fields' focus
func (m *Model) updateFocus() {
	if m.currentField == fieldToken {
		m.tokenInput.Focus()
		return
	}
	m.tokenInput.Blur() // fieldSubmit is a button, not an input
}

// authenticate starts authentication
func (m *Model) authenticate() tea.Cmd {
	url := m.config.Forge.URL
	token := strings.TrimSpace(m.tokenInput.Value())

	// Defence in depth: the auto-login path comes here without handleEnterKey,
	// and a stored token of blanks must not start an anonymous call.
	if token == "" {
		return nil
	}
	if url == "" {
		m.error = m.missingURLMessage()
		return nil
	}

	// Copy the necessary data BEFORE the goroutine (Rule 110)
	storage := m.secrets.Storage
	config := m.config
	forgeType := m.config.Forge.Type

	// Asynchronous command
	return func() tea.Msg {
		// Create the auth
		auth := session.NewAuth(storage)

		// There is no longer a choice: the token always goes to the store.
		result, err := auth.Authenticate(context.Background(), forgeType, url, token)
		if err != nil {
			return AuthResultMsg{Error: err}
		}

		// Nothing to save: the URL came from the configuration and the token is
		// already in the store. ConfigToSave is kept so the router's handler is
		// unchanged, but it carries no edit of this view's making.
		return AuthResultMsg{
			Forge:        result.Forge,
			User:         result.User,
			Error:        nil,
			SaveWarning:  result.SaveWarning,
			ConfigToSave: config,
		}
	}
}

// logout signs the user out
func (m *Model) logout() tea.Cmd {
	url := m.config.Forge.URL
	storage := m.secrets.Storage

	// Asynchronous command
	return func() tea.Msg {
		// Create the auth
		auth := session.NewAuth(storage)

		// Remove the credentials from storage
		_ = auth.Logout(url) // Ignore the error, we log out anyway

		// Do NOT modify m.config here (Rule 110) - do it in Update()
		// Return the logout-complete message
		return LogoutCompleteMsg{}
	}
}
	secrets credentials.Selection

	// notices report what the migration off plaintext configuration did, if
	// anything. Shown once, on the view that owns the token.
	notices []string

	currentField int

	authenticated bool // True if the user is authenticated
	// user is the signed-in user, zero when there is none — m.authenticated is
	// the flag, and a second way to ask is how the two came to disagree.
	user forge.User

	authenticating bool
	spinner        spinner.Model
	error          string
	success        string
	warning        string // Non-blocking warning (e.g. credentials save failure)

	// validation holds the token's field error once a submit was refused
	// (DEVDESK-292); the footer derives its message from it at every render.
	validation components.Validation
	marks      components.InvalidMarks

	// footer carries the messages other parts of the app post to this view (Rule 128).
	footer components.FooterMessage

	width  int
	height int
}

// forgeTypeOf reads the context's platform, empty-safe. It exists because New
// runs before the model does, so m.vocab() is not available yet.
func forgeTypeOf(cfg *config.Config) string {
	if cfg == nil {
		return ""
	}
	return cfg.Forge.Type
}

// New creates a new authentication view
func New(cfg *config.Config, secrets credentials.Selection, notices []string) *Model {
	// Create the inputs
	tokenInput := textinput.New()
	// The example token is the forge's. It was a GitLab literal here, and it
	// escaped vocabtest because `glpat-` names no forge — the guard looks for
	// the platforms' names, and a token prefix is forge-specific without
	// carrying one.
	tokenInput.Placeholder = forge.VocabularyFor(forgeTypeOf(cfg)).TokenPlaceholder
	tokenInput.CharLimit = 100
	tokenInput.SetWidth(60)
	tokenInput.EchoMode = textinput.EchoPassword
	tokenInput.EchoCharacter = '•'
	theme.StyleTextInput(&tokenInput)

	// Spinner
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	// Focus on the first field
	tokenInput.Focus()

	return &Model{
		config:         cfg,
		tokenInput:     tokenInput,
		secrets:        secrets,
		notices:        notices,
		currentField:   fieldToken,
		authenticating: false,
		spinner:        sp,
		error:          "",
		success:        "",
	}
}

// Init initializes the model
func (m *Model) Init() tea.Cmd {
	// Try to load saved credentials
	return tea.Batch(
		textinput.Blink,
		m.loadSavedCredentials(),
	)
}

// loadSavedCredentials retrieves the token from the secrets store.
package auth

import (
	"strings"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/forge"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

func (m Model) InEditMode() bool {
	// In edit mode only if a textinput has focus
	// and the user is not currently authenticating
	// If authenticated, we are no longer in edit mode
	if m.authenticated || m.authenticating {
		return false
	}
	// In edit mode if we're on one of the text fields
	return m.currentField == fieldToken
}

func (m Model) GetShortcuts() shortcut.Shortcuts {
	return []shortcut.Shortcut{
		{Key: "enter", Description: "Submit / Advance field"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight returns the footer height for this view (Rule 124).
func (m Model) GetFooterHeight() int {
	return 2 // empty line + info line
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
func (m Model) RenderFooter(width int) string {
	return theme.EmptyLineBg(width) + "\n" + m.footer.View(width, m.validation.Status())
}

// vocab is the wording of the forge this context targets. Resolved from the
// config rather than carried on shared.State: the title and the help are needed
// before any session exists, so a value hanging off a live Forge would be
// unavailable exactly where it is needed most.
func (m Model) vocab() forge.Vocabulary {
	if m.config == nil {
		return forge.VocabularyFor("")
	}
	return forge.VocabularyFor(m.config.Forge.Type)
}

func (m Model) GetTitle() string {
	forgeType := ""
	if m.config != nil {
		forgeType = m.config.Forge.Type
	}
	return theme.ForgeIcon(forgeType) + " " + m.vocab().Name + " Authentication"
	}

	return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1).Render(strings.Join(sections, "\n"))
}

func (m *Model) renderForm() string {
	var b strings.Builder

	// Spinner if authentication is in progress
	if m.authenticating {
		b.WriteString(theme.SpinnerMessage(m.spinner.View(), "Authenticating...") + "\n\n")
		return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1, 2).Render(b.String())
	}

	// If authenticated, show the "Logged in" view
	if m.authenticated {
		return m.renderLoggedInView()
	}

	// The URL is shown, not edited: it is configuration, and the configuration
	// view owns it. Both views used to write it, so neither was authoritative.
package auth

import (
	"errors"
	"strings"
	"testing"

	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-375: "Authenticating..." is a footer status with the shared activity
// dot, driven by the router frame; the body keeps its form (Rule 128).

func authFooterPlain(m *Model) string { return ansi.Strip(m.RenderFooter(160)) }

func authDots(s string) (on, off int) {
	return strings.Count(s, indicator.Glyph(indicator.Running, true)),
		strings.Count(s, indicator.Glyph(indicator.Running, false))
}

// blinker is the contract the router reads to arm its animation chain. It is
// asserted at run time so a missing method is a failed assertion, not a build error.
type blinker interface{ WantsBlink() bool }

func wantsBlink(t *testing.T, m *Model) bool {
	t.Helper()
	b, ok := any(m).(blinker)
	if !ok {
		t.Error("Model has no WantsBlink() bool: the router cannot keep the dot blinking")
		return false
	}
	return b.WantsBlink()
}

func authenticatingModel(t *testing.T) *Model {
	t.Helper()
	m := newTestModel(t, testConfig(), newFakeStorage())
	m, _ = step(t, m, AuthStartMsg{})
	return m
}

func TestAuthStartShowsTheDotAndTheTextInTheFooter(t *testing.T) {
	m := authenticatingModel(t)

	plain := authFooterPlain(m)
	if !strings.Contains(plain, "Authenticating...") {
		t.Errorf("the footer does not say Authenticating...\n%s", plain)
	}
	if on, off := authDots(plain); on+off != 1 {
		t.Errorf("want exactly one dot in the footer, got on=%d off=%d\n%s", on, off, plain)
	}
	if !wantsBlink(t, m) {
		t.Error("WantsBlink() = false while authenticating")
	}
}

func TestTheBodyKeepsTheFormWhileAuthenticating(t *testing.T) {
	m := authenticatingModel(t)

	out := ansi.Strip(m.Render())
	if strings.Contains(out, "Authenticating...") {
		t.Error("the body still carries Authenticating...: it belongs to the footer")
	}
	if !strings.Contains(out, "Personal Access Token") || !strings.Contains(out, "Login") {
		t.Errorf("the form is gone from the body while authenticating\n%s", out)
	}
}

func TestNoBrailleWhileAuthenticating(t *testing.T) {
	m := authenticatingModel(t)

	for name, out := range map[string]string{"body": m.Render(), "footer": m.RenderFooter(160)} {
		for _, r := range out {
			if r >= 0x2800 && r <= 0x28FF {
				t.Errorf("%s carries a braille glyph %q", name, r)
				break
			}
		}
	}
}

func TestTheFrameMovesTheFooterDot(t *testing.T) {
	m := authenticatingModel(t)
	m, _ = step(t, m, jobs.FrameMsg{Blink: true})
	on, _ := authDots(authFooterPlain(m))
	m, _ = step(t, m, jobs.FrameMsg{Blink: false})
	_, off := authDots(authFooterPlain(m))
	if on != 1 || off != 1 {
		t.Errorf("the dot did not follow the frame: on in phase true = %d, off in phase false = %d", on, off)
	}
}

func TestAuthResultClearsTheDot(t *testing.T) {
	m := authenticatingModel(t)

	m, _ = step(t, m, AuthResultMsg{Error: errors.New("401 Unauthorized")})

	plain := authFooterPlain(m)
	if on, off := authDots(plain); on+off != 0 {
		t.Errorf("the dot outlived the result: on=%d off=%d\n%s", on, off, plain)
	}
	if strings.Contains(plain, "Authenticating...") {
		t.Error("Authenticating... outlived the result")
	}
	if wantsBlink(t, m) {
		t.Error("WantsBlink() = true after the result")
	}
	if !strings.Contains(ansi.Strip(m.Render()), "401") {
		t.Error("the error is no longer rendered after a failed login")
	}
}

func TestIdleModelHasNoDotAndNoBlink(t *testing.T) {
	m := newTestModel(t, testConfig(), newFakeStorage())
	if on, off := authDots(authFooterPlain(m)); on+off != 0 {
		t.Errorf("an idle form shows a dot: on=%d off=%d", on, off)
	}
	if wantsBlink(t, m) {
		t.Error("an idle model asks for the blink")
	}
}

func TestEnterIsIgnoredWhileAuthenticating(t *testing.T) {
	m := authenticatingModel(t)
	m.tokenInput.SetValue("glpat-x")
	setConfigURL(m, "https://gitlab.example.com")

	m, cmd := step(t, m, testutil.Key("enter"))

	if cmd != nil {
		t.Error("enter issued a command while authentication was in flight")
	}
	if !m.authenticating {
		t.Error("enter stopped the authentication")
	}
}

func TestARefusedSubmitKeepsTheValidationErrorAndNoDot(t *testing.T) {
	m := newTestModel(t, testConfig(), newFakeStorage())
	setConfigURL(m, "https://gitlab.example.com")
	m.tokenInput.SetValue("")
	m.currentField = fieldSubmit

	m, _ = step(t, m, testutil.Key("enter"))

	plain := authFooterPlain(m)
	if on, off := authDots(plain); on+off != 0 {
		t.Errorf("a refused submit shows a dot: on=%d off=%d", on, off)
	}
	if strings.TrimSpace(plain) == "" || strings.Contains(plain, "Authenticating") {
		t.Errorf("the footer lost the validation error\n%s", plain)
	}
}
package containers

import (
	"fmt"
	"strings"
	"time"

	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/docker"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// observedState maps what the engine reports for a container onto the shared
// activity vocabulary (Rule 125). A running container is Idle: the nominal
// state shows the container icon, not a glyph. An exit without a known code is
// Failed, so a possible crash is never shown as a clean stop. Engine synonyms
// (podman's configured, initialized, stopping...) and anything unknown fall
// back to Unknown.
func observedState(c docker.Container) indicator.State {
	switch c.State {
	case "running":
		return indicator.Idle
	case "restarting":
		return indicator.Restarting
	case "paused":
		return indicator.Suspended
	case "exited", "stopped":
		if c.Facts.HasExitCode && c.Facts.ExitCode == 0 {
			return indicator.Skipped
		}
		return indicator.Failed
	case "dead":
		return indicator.Failed
	}
	return indicator.Unknown
}

// restIcon is what the activity column shows for a container that is Idle.
func restIcon(docker.Container) string { return theme.IconContainer }

// restStyle colours restIcon with the container role (plain text by default).
func restStyle(docker.Container) lipgloss.Style {
	return theme.IconStyle(theme.IconRoleContainer)
}

// ActivityTables returns the read-only face of the view's table, keyed by the
// name the activity-column guard (internal/app) knows it by.
func (m Model) ActivityTables() map[string]datatable.ActivityTable {
	return map[string]datatable.ActivityTable{"containers": &m.containerTable}
}

// WantsBlink is the router's BlinkingView hook: true while a row action is in
// flight, so the router frames the view for the running dot's blink.
func (m Model) WantsBlink() bool {
	return len(m.containerTable.BusyLabels()) > 0 || m.status().Activity
}

// observedText is the footer sentence for a container at rest, without a
// glyph: the glyph is added by components.DescribeRow from observedState.
func observedText(c docker.Container) string {
	f := c.Facts
	ago := ""
	if f.HasAge {
		ago = " — " + agoPhrase(f.Age, "just now")
	}
	switch c.State {
	case "running":
		if f.HasAge {
			if f.Age < time.Minute {
				return "Running for less than a minute"
			}
			return "Running since " + theme.AgoFor(f.Age)
		}
		return "Running"
	case "restarting":
		if f.HasExitCode {
			return fmt.Sprintf("Restarting — last exit code %d", f.ExitCode)
		}
		return "Restarting"
	case "paused":
		return "Paused"
	case "created":
		return "Created, never started"
	case "exited", "stopped":
		switch {
		case !f.HasExitCode:
			return "Exited (exit code unknown)"
		case f.ExitCode == 0:
			return "Exited cleanly (code 0)" + ago
		}
		return fmt.Sprintf("Exited with code %d", f.ExitCode) + ago
	case "dead":
		return "Dead — the engine could not stop it cleanly"
	case "removing":
		return "Removing"
	}
	if c.State == "" {
		return ""
	}
	return strings.ToUpper(c.State[:1]) + c.State[1:]
}

// agoPhrase is theme.AgoFor, except that "now" (under a minute) reads badly
// inside a sentence, so it is replaced by the given wording.
func agoPhrase(d time.Duration, underMinute string) string {
	if d < time.Minute {
		return underMinute
	}
	return theme.AgoFor(d)
}

// selectedDetail is what the footer says about the selected container: the
// action running on it, else its observed state in words. Empty when nothing
// is selected.
func (m Model) selectedDetail() sharedcomponents.RowDetail {
	c := m.getSelectedContainer()
	if c == nil {
		return sharedcomponents.RowDetail{}
	}
	if label, ok := m.containerTable.BusyLabel(c.ID); ok {
		return sharedcomponents.RowDetail{
			Glyph:  indicator.Glyph(indicator.Running, true), // the footer glyph never blinks
			Lead:   strings.TrimSuffix(label, c.Name),
			Target: c.Name,
		}
	}
	return sharedcomponents.DescribeRow(sharedcomponents.RowQuery{
		Observed: observedState(*c), ObservedText: observedText(*c),
	}).Detail
}

